class AssessmentSystem:
    def __init__(self):
        self.students = {}

    def add_student(self, name, grade, major):
        self.students[name] = {'name': name, 'grade': grade, 'major': major, 'courses': {}}

    def add_course_score(self, name, course, score):
        if name in self.students:
            self.students[name]['courses'][course] = score

    def get_gpa(self, name):
        if name in self.students and self.students[name]['courses']:
            scores = [s for s in self.students[name]['courses'].values() if s is not None]
            if scores:
                return sum(scores) / len(scores)
        return None

    def get_all_students_with_fail_course(self):
        fail_students = []
        for name, student in self.students.items():
            if any(score is not None and score < 60 for score in student['courses'].values()):
                fail_students.append(name)
        return fail_students

    def get_course_average(self, course):
        scores = []
        for student in self.students.values():
            if course in student['courses'] and student['courses'][course] is not None:
                scores.append(student['courses'][course])
        if scores:
            return sum(scores) / len(scores)
        return None

    def get_top_student(self):
        if not self.students:
            return None
        top_student = None
        top_gpa = -1
        for name in self.students:
            gpa = self.get_gpa(name)
            if gpa is not None and gpa > top_gpa:
                top_gpa = gpa
                top_student = name
        return top_student

